insert into public.diagnostico_items
  (id, area, tipo, peso, elo, elo_base, enunciado, opciones, fen, correcta, solucion, alternas, explica, lichess, rating)
values
  ('est_peones_colgantes', 'estrategia', 'opcion', 2, 1280, 1450, '¿Qué son los «peones colgantes»?', '["Dos peones propios juntos, sin otros que los apoyen","Peones que están por coronar en la jugada siguiente","Peones que fueron capturados al paso por el rival","Peones del jugador que se quedó sin tiempo"]'::jsonb, null, 0, null, null, 'Son fuerza y debilidad a la vez: dan espacio y movilidad mientras avanzan juntos, pero como ningún peón los defiende, son blanco fijo si se los logra frenar. Todo depende de si pueden avanzar o no.', null, null),
  ('est_iniciativa', 'estrategia', 'opcion', 2, 1130, 950, '¿Qué significa tener la «iniciativa» en una partida?', '["Amenazar sin parar y obligar al rival a responder","Haber hecho la primera jugada de toda la partida","Tener más piezas en el tablero que las del rival","Haber enrocado antes de que enrocara el rival"]'::jsonb, null, 0, null, null, 'Quien la tiene marca el ritmo: el rival gasta todas sus jugadas defendiéndose y nunca llega a su propio plan. La iniciativa se puede perder en una jugada, y por eso a veces se paga material por conservarla.', null, null),
  ('est_tempo', 'estrategia', 'opcion', 1, 1060, 950, 'En términos de apertura y estrategia, ¿qué es un «tiempo» (tempo)?', '["Cada jugada aprovechada para mejorar algo","El tiempo total que dura la partida en el reloj","Un tipo de sacrificio que se hace en la apertura","Otra forma de nombrar el jaque al rey"]'::jsonb, null, 0, null, null, 'Cada jugada cuesta un tiempo: si desarrolla o mejora la posición, está bien gastada; si repite o deshace, se perdió. Ganar tiempos atacando algo mientras uno se desarrolla es la forma más barata de sacar ventaja.', null, null),
  ('est_ataque_minoria', 'estrategia', 'opcion', 3, 1650, 1700, '¿En qué consiste el «ataque de minoría»?', '["Avanzar los pocos peones de un flanco para dejarle una debilidad","Atacar únicamente con las piezas menores, jamás con las mayores","Entregar de una sola vez todos los peones de un mismo flanco","Jugar siempre con menos piezas en el tablero que el rival"]'::jsonb, null, 0, null, null, 'Se avanzan dos peones contra tres, no para coronar sino para cambiarlos y que al rival le quede un peón aislado o retrasado en esa zona. Es el plan típico del Gambito de Dama con estructura Carlsbad.', null, null),
  ('est_casillas_debiles', 'estrategia', 'opcion', 2, 1190, 1450, '¿A qué se le llama un «complejo de casillas débiles»?', '["A un grupo de casillas de un color que ya nadie cubre","A las casillas donde nunca puede haber ninguna pieza","A las cuatro casillas centrales del tablero de ajedrez","A las casillas donde un peón puede llegar a coronar"]'::jsonb, null, 0, null, null, 'Al cambiarse, por ejemplo, el alfil de casillas claras, todas las claras cerca del rey quedan sin quien las controle, y ahí se instalan las piezas rivales. Un alfil que se cambia no se recupera: esa debilidad es para toda la partida.', null, null),
  ('est_pareja_alfiles_abierta', 'estrategia', 'opcion', 1, 980, 1200, 'Si tienes la pareja de alfiles contra alfil y caballo, ¿qué tipo de posición te conviene buscar?', '["Abierta, con las diagonales largas despejadas","Cerrada del todo, con los peones bien trabados","Una en la que puedas cambiar tus alfiles rápido","Una donde no se abra ninguna línea nunca"]'::jsonb, null, 0, null, null, 'Los dos alfiles cubren casillas de los dos colores y barren el tablero cuando hay diagonales libres. Con la posición cerrada, en cambio, el caballo salta y ellos miran una pared de peones.', null, null),
  ('est_enroques_opuestos', 'estrategia', 'opcion', 3, 1430, 1450, 'Si las blancas enrocan corto y las negras largo, ¿qué estrategia se vuelve muy fuerte para los dos bandos?', '["Avanzar los peones contra el rey del rival","No mover ningún peón por el resto de la partida","Cambiar todas las piezas para llegar a un final","Volver a enrocar hacia el flanco contrario"]'::jsonb, null, 0, null, null, 'Como el propio rey está en el otro flanco, avanzar esos peones no lo debilita: es ataque puro y sin costo. Se convierte en una carrera, y ahí cada tiempo vale una pieza.', null, null),
  ('est_cambiar_bajo_presion', 'estrategia', 'opcion', 2, 1270, 1200, 'Si tu posición está bajo mucha presión, aunque el material siga igualado, ¿qué recurso suele aliviar la defensa?', '["Cambiar piezas para simplificar y bajar el peligro","Evitar cualquier cambio de piezas a toda costa posible","Avanzar los peones que cubren al propio rey ya","Sacar la dama a atacar ella sola por su cuenta"]'::jsonb, null, 0, null, null, 'Un ataque necesita piezas: cada una que se cambia le quita fuerza, aunque no se gane material. Por eso quien defiende busca cambios y quien ataca los evita.', null, null),
  ('est_evaluar_posicion', 'estrategia', 'opcion', 1, 750, 950, 'Al evaluar una posición en el medio juego, ¿qué conviene mirar además del material?', '["Rey, actividad de las piezas, peones y espacio","Únicamente cuántas piezas quedan en el tablero","Solamente el tiempo que queda en el reloj","Nada más: solo si ya se enrocó o todavía no"]'::jsonb, null, 0, null, null, 'El material es un factor entre varios. Un peón de menos con las piezas activas y el rey rival expuesto suele ser mejor negocio que un peón de más con todo dormido.', null, null),
  ('cal_que_es_calcular', 'calculo', 'opcion', 1, 880, 700, 'En ajedrez, ¿qué significa exactamente «calcular»?', '["Ver en la cabeza jugadas futuras y sus consecuencias","Contar cuántas piezas quedan sobre el tablero de juego","Sumar el tiempo que queda en el propio reloj","Aprenderse de memoria variantes de apertura"]'::jsonb, null, 0, null, null, 'Es seguir una secuencia concreta —mi jugada, su respuesta, mi jugada— sin tocar las piezas, y saber cómo queda el tablero al final. No es adivinar: es verificar.', null, null),
  ('cal_cambio_igual', 'calculo', 'opcion', 2, 1260, 700, 'Si cambias tu alfil por el caballo del rival, y no hay ninguna otra captura, ¿qué pasó con el material?', '["Sigue igualado: los dos perdieron una menor","Quedaste tú con una pieza de ventaja clara","Quedó el rival con una pieza de ventaja clara","Se declaran tablas de manera automática"]'::jsonb, null, 0, null, null, 'Alfil y caballo valen lo mismo en la tabla, así que el balance no se mueve. Lo que sí cambia es el tipo de posición que queda, y eso puede favorecer a uno de los dos.', null, null),
  ('cal_contar_atacantes', 'calculo', 'opcion', 1, 1010, 950, 'Antes de lanzar una serie de capturas en una casilla, ¿qué es fundamental contar primero?', '["Cuántos atacan, cuántos defienden y qué vale cada uno","Solo cuántas piezas propias quedan todavía en el tablero","El tiempo que a cada uno le queda en el reloj","El color de la casilla donde se cruzan las piezas"]'::jsonb, null, 0, null, null, 'No alcanza con contar cabezas: importa el orden de valor. Tres atacantes contra dos defensores puede ser mal negocio si los atacantes son la dama y las torres.', null, null),
  ('cal_arbol_variantes', 'calculo', 'opcion', 2, 1340, 1200, '¿Qué es un «árbol de variantes» al calcular una posición?', '["Las líneas que se abren según responda el rival","Un dibujo que se hace en papel antes de jugar","Una apertura con muchísima teoría acumulada","La planilla escrita de una partida ya terminada"]'::jsonb, null, 0, null, null, 'Cada jugada candidata abre ramas según lo que conteste el rival, y cada rama abre otras. Calcular bien es podar ese árbol: mirar pocas ramas, pero las que importan.', null, null),
  ('cal_precision_vs_profundidad', 'calculo', 'opcion', 2, 1360, 1450, 'Sobre «cuántas jugadas hay que calcular por delante», ¿qué es más importante que ver muy lejos?', '["Ver con precisión hasta donde haga falta","Calcular siempre al menos diez jugadas exactas","No calcular nunca más de una sola jugada","Nada: la cantidad de jugadas no importa"]'::jsonb, null, 0, null, null, 'Tres jugadas bien calculadas valen más que ocho a medias: un error a la segunda jugada invalida todo lo que viene después. Se calcula hasta que la posición se aquieta, no hasta un número fijo.', null, null),
  ('cal_a_ciegas', 'calculo', 'opcion', 1, 950, 1200, '¿Para qué sirve practicar cálculo «a ciegas», visualizando sin mover las piezas?', '["Para entrenar a ver el tablero futuro en la cabeza","Para poder jugar torneos sin tablero delante de uno","Para memorizar aperturas mucho más rápido","Para no tener que aprender la regla del enroque"]'::jsonb, null, 0, null, null, 'Obliga a construir la imagen de la posición futura sin apoyarse en lo que se ve. Es exactamente la habilidad que falla cuando una combinación «se veía bien» y no funcionaba.', null, null),
  ('cal_amenaza_rival', 'calculo', 'opcion', 1, 780, 950, 'Antes de decidir una jugada, ¿qué conviene revisar además de las propias ideas?', '["Qué amenaza el rival con lo que acaba de jugar","Solo cuántas piezas propias quedan en el tablero","Cómo terminó la última partida que se jugó","De qué color es la casilla del propio rey"]'::jsonb, null, 0, null, null, 'La pregunta que más partidas salva es «¿para qué jugó eso?». Ejecutar el propio plan sin mirar la amenaza del rival es la causa número uno de las derrotas por descuido.', null, null),
  ('cal_recaptura_cual', 'calculo', 'opcion', 2, 1310, 1200, 'Después de una captura, ¿qué conviene comprobar antes de dar por obvia la recaptura?', '["Todas las piezas que pueden recapturar ahí","Solamente si el rey sigue estando en jaque","Si el enroque ya se hizo o todavía no","El valor total de las piezas que quedan"]'::jsonb, null, 0, null, null, 'Muchas veces hay dos o tres piezas que pueden recapturar, y la elección cambia todo: con cuál se recaptura decide si la columna queda abierta, si el peón queda doblado o si la pieza queda mal puesta.', null, null),
  ('cal_legalidad', 'calculo', 'opcion', 2, 1130, 1200, 'Después de calcular una combinación prometedora, ¿qué último paso no hay que saltarse?', '["Comprobar que cada jugada de la línea es legal","Anunciar la combinación al rival en voz alta","Ofrecerle tablas al rival antes de empezarla","Anotarla en la planilla antes de jugar nada"]'::jsonb, null, 0, null, null, 'Es facilísimo calcular moviendo una pieza que en realidad está clavada, o dejando al propio rey en jaque. Antes de confiar en la combinación, se repasa que cada jugada exista de verdad.', null, null),
  ('cal_espejismo', 'calculo', 'opcion', 3, 1520, 1450, '¿Qué es un «espejismo táctico» al calcular una combinación?', '["Una línea que parece ganar hasta que aparece la defensa","Una jugada que en realidad es ilegal pero parece legal","Un patrón de mate que no llega a funcionar jamás","Un tipo de sacrificio que siempre resulta correcto"]'::jsonb, null, 0, null, null, 'La combinación se ve preciosa y falla por una jugada que está una más adelante. Por eso hay que buscar activamente la mejor defensa del rival, no la que uno espera que juegue.', null, null),
  ('cal_forzadas_faciles', 'calculo', 'opcion', 3, 1460, 1200, '¿Por qué las líneas «forzadas» son más fáciles de calcular que las libres?', '["Porque hay menos ramas que revisar","Porque las forzadas siempre terminan en mate","Porque en ellas no hace falta pensar nada","Porque las líneas libres son siempre ilegales"]'::jsonb, null, 0, null, null, 'Si el rival tiene una sola respuesta razonable, el árbol es una línea recta y se puede calcular muy profundo. Por eso conviene empezar mirando jaques y capturas: son lo más forzado que hay.', null, null),
  ('cal_evaluar_final', 'calculo', 'opcion', 2, 1340, 1450, 'Al terminar de calcular una secuencia larga, ¿qué es tan importante como ver las jugadas?', '["Ver cómo queda la posición final y si conviene","Anotar cada jugada en la planilla antes de jugar","Contar cuántos minutos se gastaron pensándola","Preguntarle al árbitro si la secuencia está bien"]'::jsonb, null, 0, null, null, 'Se puede calcular ocho jugadas sin un error y equivocarse igual, si la posición del final no era tan buena como parecía. Calcular y evaluar son dos habilidades distintas y las dos hacen falta.', null, null),
  ('cal_amenaza_de_mate', 'calculo', 'opcion', 1, 810, 950, 'Si el rival amenaza dar mate en su jugada siguiente, ¿qué prioridad tiene atender esa amenaza?', '["Máxima: antes que cualquier plan propio","Ninguna: se puede ignorar si uno gana material","Solo importa si al rival le queda la dama","Solo en los finales, nunca en la apertura"]'::jsonb, null, 0, null, null, 'El mate termina la partida, así que anula cualquier otra cuenta. Aunque estés ganando una torre del otro lado del tablero, primero se para el mate — aunque cueste material.', null, null),
  ('cal_poco_tiempo', 'calculo', 'opcion', 2, 1210, 1200, 'Con poco tiempo en el reloj, ¿qué conviene priorizar al calcular?', '["Las líneas forzadas y seguras, que se verifican","Calcular la partida entera hasta el final","No calcular nada y jugar lo primero que salga","Ofrecer tablas de inmediato, sin mirar nada"]'::jsonb, null, 0, null, null, 'Una combinación especulativa necesita tiempo para comprobarse, y con la bandera cerca no lo hay. Con apuro se juega lo que se puede verificar rápido, aunque sea menos ambicioso.', null, null),
  ('cal_ver_vs_calcular', 'calculo', 'opcion', 1, 930, 1200, '¿Cuál es la diferencia entre «ver» una idea táctica y «calcularla»?', '["Verla es notarla; calcularla es comprobar que sirve","Son exactamente lo mismo, no hay ninguna diferencia","Calcular es más lento y además menos preciso","No se puede ver una idea sin calcularla antes"]'::jsonb, null, 0, null, null, 'Reconocer el patrón es el chispazo; calcular es el trabajo de confirmar que en esta posición concreta funciona. Muchos errores vienen de jugar el chispazo sin hacer el trabajo.', null, null),
  ('cal_precision_finales', 'calculo', 'opcion', 2, 1250, 1450, '¿Por qué el cálculo en los finales suele pedir más precisión que en el medio juego?', '["Porque un solo tiempo cambia el resultado","Porque en los finales las piezas se mueven distinto","Porque en los finales no hay nada que calcular","Porque el reloj corre más rápido en los finales"]'::jsonb, null, 0, null, null, 'Con pocas piezas no hay con qué compensar un error: la diferencia entre ganar y empatar suele ser una casilla o un turno. En el medio juego un error se disimula; en el final, no.', null, null),
  ('cal_entrenar_puzles', 'calculo', 'opcion', 1, 850, 700, '¿Cuál es una de las formas más efectivas de entrenar la capacidad de cálculo?', '["Resolver ejercicios tácticos con regularidad","Memorizar únicamente variantes de apertura","Jugar solo partidas rapidísimas, sin pensar","No analizar nunca las propias partidas"]'::jsonb, null, 0, null, null, 'Los puzles entrenan las dos mitades: reconocer el patrón y calcular hasta confirmarlo. Y conviene resolverlos sin mover las piezas, que es como hay que hacerlo en la partida.', null, null),
  ('mae_titulos_fide', 'maestria', 'opcion', 1, 920, 700, 'Entre los títulos oficiales de la FIDE, ¿cuál es el de mayor jerarquía?', '["Gran Maestro (GM)","Maestro Internacional","Maestro FIDE (FM)","Candidato a Maestro"]'::jsonb, null, 0, null, null, 'De mayor a menor: Gran Maestro, Maestro Internacional, Maestro FIDE y Candidato a Maestro. Se consiguen con normas en torneos y un Elo mínimo, y una vez otorgados no se pierden.', null, null),
  ('mae_pgn', 'maestria', 'opcion', 1, 620, 700, '¿Qué es el formato PGN, usado para guardar partidas de ajedrez?', '["Un archivo de texto con las jugadas y los datos","Un tipo particular de reloj digital de torneo","El nombre de uno de los motores más conocidos","Un formato solo para imágenes de tableros"]'::jsonb, null, 0, null, null, 'PGN quiere decir Portable Game Notation: texto plano con las jugadas más los datos de la partida (jugadores, fecha, resultado). Lo abre cualquier programa, y por eso es el formato en que se comparten partidas.', null, null),
  ('mae_round_robin', 'maestria', 'opcion', 2, 1320, 700, '¿Cómo se llama el formato de torneo en el que cada jugador enfrenta a todos los demás?', '["Todos contra todos (round robin)","Sistema suizo de emparejamiento","Eliminación directa por rondas","Sistema Scheveningen por equipos"]'::jsonb, null, 0, null, null, 'Cada participante juega contra cada uno de los demás, una o dos veces. Es el formato más justo, pero solo sirve para grupos chicos: con 30 jugadores harían falta 29 rondas.', null, null),
  ('mae_capablanca', 'maestria', 'opcion', 1, 920, 700, 'El excampeón mundial cubano José Raúl Capablanca es especialmente recordado por…', '["Su técnica clarísima y precisa en los finales","Ser el primero en usar relojes en el ajedrez","Haber inventado la regla del enroque largo","No haber perdido jamás ni una sola partida"]'::jsonb, null, 0, null, null, 'Su juego parecía fácil: cambiaba a finales que sabía ganar y los ganaba sin aspavientos. Sus finales se siguen usando como material de enseñanza casi un siglo después.', null, null),
  ('mae_deep_blue', 'maestria', 'opcion', 2, 1360, 700, '¿Qué ocurrió en el famoso enfrentamiento entre Garry Kaspárov y la computadora Deep Blue en 1997?', '["Ganó Deep Blue, y fue un hito histórico","Kaspárov ganó sin perder ninguna partida","El match se suspendió sin ningún resultado","Fue la primera vez que se usó reloj digital"]'::jsonb, null, 0, null, null, 'La máquina de IBM venció al campeón del mundo en un match a seis partidas. Fue la primera vez que una computadora le ganaba un match al mejor jugador humano del momento.', null, null),
  ('mae_incremento', 'maestria', 'opcion', 1, 930, 950, 'En un reloj con «incremento» —por ejemplo 90 minutos + 30 segundos—, ¿qué significa ese segundo número?', '["Se suman esos segundos después de cada jugada","El reloj sube esa cantidad una sola vez, al inicio","El rival pierde ese tiempo en cada jugada suya","La partida dura como mucho esos segundos extra"]'::jsonb, null, 0, null, null, 'Cada vez que el jugador completa una jugada, el reloj le devuelve esos segundos. Existe para que nadie pierda una posición ganada por no tener tiempo material de mover las piezas.', null, null),
  ('mae_suizo', 'maestria', 'opcion', 2, 1350, 950, '¿Cómo funciona el «sistema suizo» en un torneo?', '["Empareja por puntaje parecido, sin eliminar a nadie","Los que pierden quedan eliminados del torneo","Todos enfrentan a todos los demás, una sola vez","Se juega una única partida eliminatoria por ronda"]'::jsonb, null, 0, null, null, 'En cada ronda se enfrentan los que llevan puntaje parecido, y nadie queda fuera: todos juegan todas las rondas. Es lo que permite correr un torneo de 200 personas en nueve rondas.', null, null),
  ('mae_evaluacion_motor', 'maestria', 'opcion', 1, 1050, 950, 'Cuando un motor de ajedrez muestra «+1.5» para las blancas, ¿qué quiere decir?', '["Que llevan ventaja de algo más de un peón","Que están a 1.5 jugadas de dar jaque mate","Que a la partida le quedan 1.5 horas de juego","Que hay 1.5 piezas atacadas en el tablero"]'::jsonb, null, 0, null, null, 'Los motores miden en «peones»: +1.5 es una ventaja de peón y medio. No garantiza ganar — con +1.5 se pierden partidas todos los días —, es una estimación de cuánto mejor está una posición.', null, null),
  ('mae_partida_del_siglo', 'maestria', 'opcion', 3, 1420, 950, '¿Por qué se conoce como «la Partida del Siglo» a Donald Byrne contra Bobby Fischer, de 1956?', '["Porque Fischer, con 13 años, sacrificó la dama","Porque fue la partida más larga que se registró","Porque terminó en tablas por ahogado del rey","Porque se jugó entera sin reloj de ajedrez"]'::jsonb, null, 0, null, null, 'Fischer tenía trece años y entregó la dama contra un maestro adulto, con una combinación que se veía muchas jugadas más adelante. Es la partida con la que se le presentó al mundo.', null, null),
  ('mae_ajedrez960', 'maestria', 'opcion', 2, 1240, 950, '¿En qué consiste el «Ajedrez960» (Fischer Random), inventado por Bobby Fischer?', '["La fila de piezas se sortea antes de empezar","Se juega con 960 peones extra sobre el tablero","El tablero tiene 960 casillas en lugar de 64","Cada jugador tiene 9 minutos con 60 de incremento"]'::jsonb, null, 0, null, null, 'Las piezas de la primera fila se ordenan al azar entre 960 posiciones válidas —los peones no se mueven de sitio—, así que la teoría memorizada no sirve y hay que pensar desde la jugada 1. Era justo lo que a Fischer le molestaba del ajedrez de su época.', null, null),
  ('mae_elo_que_mide', 'maestria', 'opcion', 1, 940, 1200, '¿Qué mide, en términos generales, el sistema de puntuación Elo?', '["La fuerza estimada a partir de los resultados","Cuántas partidas lleva jugadas alguien en su vida","El tiempo total que dedicó una persona al ajedrez","La edad mínima para poder competir en torneos"]'::jsonb, null, 0, null, null, 'Es un número que sale de contra quién se jugó y cómo terminó. Ganarle a alguien mucho más fuerte suma bastante; ganarle a alguien mucho más débil, casi nada.', null, null),
  ('mae_libro_aperturas', 'maestria', 'opcion', 2, 1120, 1200, '¿Qué es el «libro de aperturas» que usan los motores y las bases de datos?', '["Jugadas de apertura ya conocidas, guardadas aparte","Un libro de papel obligatorio en los torneos","La lista de jugadas prohibidas por el reglamento","El manual de instrucciones del programa"]'::jsonb, null, 0, null, null, 'Son líneas ya analizadas que el motor consulta en vez de calcular: al principio de la partida hay demasiadas opciones y poco que decidir. Cuando se sale del libro, empieza a pensar.', null, null),
  ('mae_partida_inmortal', 'maestria', 'opcion', 3, 1460, 1200, '¿Por qué se conoce como «la Partida Inmortal» a Anderssen contra Kieseritzky, de 1851?', '["Porque Anderssen dio mate tras entregar casi todo","Porque la partida pasó de las doscientas jugadas","Porque terminó en tablas por triple repetición","Porque fue la primera partida jugada con reloj"]'::jsonb, null, 0, null, null, 'Anderssen sacrificó las dos torres, un alfil y la dama, y dio mate con las tres piezas menores que le quedaban. Es la partida romántica por excelencia: hoy se sabe que la defensa negra no fue la mejor, y no le quita nada.', null, null),
  ('mae_valores_relativos', 'maestria', 'opcion', 2, 1170, 1200, 'Los valores de las piezas (peón 1, menor 3, torre 5, dama 9) son útiles, pero ¿qué hay que recordar en niveles avanzados?', '["Que son una guía: la posición puede cambiarlo todo","Que son exactos y no cambian nunca con la posición","Que solo valen en el medio juego, nunca en finales","Que el valor de una pieza depende de su color"]'::jsonb, null, 0, null, null, 'Un caballo instalado en una casilla fuerte puede valer más que una torre pasiva. Los números sirven para decidir rápido en un cambio, no para evaluar una posición.', null, null),
  ('mae_jugada_ilegal', 'maestria', 'opcion', 1, 1020, 1200, 'Según las reglas actuales de la FIDE, si alguien hace una jugada ilegal por primera vez en una partida con árbitro, ¿qué suele pasar?', '["Se corrige la posición y el rival gana tiempo","Pierde la partida de inmediato, sin excepción","No pasa nada: la jugada se da por válida","Se vuelve a empezar la partida desde cero"]'::jsonb, null, 0, null, null, 'Se restablece la posición y se le añade tiempo al rival. La derrota directa queda para la reincidencia, y en partidas rápidas la sanción es más dura: conviene leer el reglamento del torneo antes de jugarlo.', null, null),
  ('mae_fortaleza', 'maestria', 'opcion', 3, 1440, 1450, 'En finales con mucha diferencia de material, ¿qué es una «fortaleza»?', '["Una defensa que da tablas porque no hay cómo abrirla","Una apertura especialmente sólida contra cualquier cosa","Un patrón de mate que se da con la torre y el alfil","Una regla que prohíbe sacrificar la dama en el final"]'::jsonb, null, 0, null, null, 'El bando con menos material se encierra en una estructura que el rival no puede abrir, y por mucho que tenga de más no progresa. Es tablas con una pieza de menos, y por eso hay que reconocerla antes de entrar en ella — o antes de dejar que el rival la arme.', null, null),
  ('mae_buchholz', 'maestria', 'opcion', 4, 1740, 1450, 'En un torneo suizo, si dos jugadores empatan en puntos, ¿qué se suele usar para desempatarlos?', '["Un desempate como el Buchholz, por los rivales","Siempre se juega una partida de desempate","Queda primero el jugador de mayor edad","Se reparte el primer lugar sin ningún criterio"]'::jsonb, null, 0, null, null, 'El Buchholz suma los puntos que hicieron los rivales que uno enfrentó: premia a quien sacó los mismos puntos contra gente más fuerte. Se conocen antes de empezar y están en el reglamento del torneo.', null, null),
  ('mae_gambito_evans', 'maestria', 'opcion', 3, 1520, 1450, '1.e4 e5 2.Cf3 Cc6 3.Ac4 Ac5 4.b4 es el…', '["Gambito Evans","Gambito de Rey","Gambito de Dama","Gambito Letón"]'::jsonb, null, 0, null, null, 'Dentro de la Italiana, las blancas ofrecen el peón de b para desviar al alfil y ganar tiempo para armar el centro con c3 y d4. Es una de las aperturas más agresivas del repertorio clásico.', null, null),
  ('mae_tablebases', 'maestria', 'opcion', 4, 1770, 1450, '¿Qué son las «tablas de finales» (endgame tablebases) generadas por computadora?', '["El resultado exacto de cada posición con pocas piezas","Un tipo de reloj especial que se usa en los finales","Un tope de jugadas tras el cual la partida es tablas","Un manual impreso con los finales clásicos"]'::jsonb, null, 0, null, null, 'Para posiciones de hasta siete piezas, están todas calculadas: se sabe el resultado con juego perfecto y la mejor jugada. Descubrieron mates forzados de más de quinientas jugadas que ningún humano habría encontrado.', null, null),
  ('mae_finales_torre_precision', 'maestria', 'opcion', 2, 1260, 1450, '¿Por qué hasta los grandes maestros cometen errores en finales de torre que parecen sencillos?', '["Porque piden una precisión extrema: un tiempo decide","Porque en esos finales rigen reglas distintas","Porque los finales de torre no se estudian nunca","Porque en ellos el reloj se detiene automáticamente"]'::jsonb, null, 0, null, null, 'Son los finales más frecuentes y de los más difíciles: una casilla de diferencia en la torre convierte una victoria en tablas. De ahí el dicho de que todos los finales de torre son tablas — que tampoco es cierto, pero explica la fama.', null, null),
  ('mae_zugzwang_reciproco', 'maestria', 'opcion', 3, 1460, 1700, '¿Qué es un «zugzwang recíproco» o mutuo?', '["Una posición donde pierde el que tenga que mover","Un zugzwang que solo puede afectar a las blancas","Una posición en la que nadie puede caer en zugzwang","Un tipo de tablas que se declaran de forma automática"]'::jsonb, null, 0, null, null, 'Está tan ajustada que el turno es una desgracia para quien lo tenga, sea quien sea. Es la base de las casillas correspondientes y de casi todos los estudios finos de finales de peones.', null, null),
  ('mae_elo_200', 'maestria', 'opcion', 4, 1730, 1700, 'En el sistema Elo, si alguien tiene unos 200 puntos más que su rival, ¿qué porcentaje de los puntos en juego suele sacarle a la larga?', '["Alrededor del 75% de los puntos","El 100%: gana siempre, sin excepción","Cerca del 50%: es prácticamente igual","Menos del 25% de los puntos en juego"]'::jsonb, null, 0, null, null, 'La fórmula predice un 75% con 200 puntos de diferencia: de cuatro partidas, tres. Cualquier partida suelta puede terminar como sea, y ahí está la gracia de jugar contra alguien más fuerte.', null, null),
  ('mae_berlinesa', 'maestria', 'opcion', 4, 1870, 1700, '1.e4 e5 2.Cf3 Cc6 3.Ab5 Cf6, dentro de la Española, corresponde a la Defensa…', '["Berlinesa","Marshall","Arkhangelsk","Schliemann"]'::jsonb, null, 0, null, null, 'Tiene fama de sólida hasta el aburrimiento. Kramnik la usó para sacarle el título a Kaspárov en 2000 sin perder una partida, y desde entonces no se fue más de la élite.', null, null),
  ('mae_teoria_juegos', 'maestria', 'opcion', 4, 1990, 1700, 'Desde la teoría de juegos, ¿qué se sabe sobre el resultado del ajedrez jugado a la perfección por los dos bandos?', '["Que tiene un resultado fijo, pero no se sabe cuál","Que ganan las blancas, y ya está bien demostrado","Que son tablas, y eso ya está también demostrado","Que no hay resultado teórico: todo depende del azar"]'::jsonb, null, 0, null, null, 'Es un juego finito, sin azar y con información perfecta, así que el teorema de Zermelo garantiza que el resultado existe. Pero hay más posiciones que átomos en el universo observable, y por eso nadie sabe cuál es.', null, null)
